-- ============================================================================
-- CallMedex service catalogue — master data load
--
-- Generated from the owner-supplied commercial sheets (kept local, gitignored):
--   CALL MEDEX LAB MASTER DATA.xlsx                     487 lab tests
--   PHYSIOTHERAPY_SCOPE_SERVICES1.xlsx                  94 physiotherapy services
--   Dental_Clinic_Hospital_Scope_of_Services_Offer_Price 298 dental services
--
-- reference_mrp is the indicative regular price; reference_offer_price is the
-- CallMedex rate where the sheet supplies one. The lab sheet supplies both. The
-- dental and physiotherapy sheets deliberately leave Offer Price blank — those
-- are negotiated per partner — so reference_offer_price is NULL there and the
-- marketplace shows no saving until a real figure exists. An invented discount
-- would be a false claim to the patient and an unfunded liability for a partner.
--
-- Idempotent: ON CONFLICT (slug) refreshes prices without duplicating rows.
-- ============================================================================

BEGIN;

ALTER TABLE service_catalog DROP CONSTRAINT IF EXISTS service_catalog_category_check;
ALTER TABLE service_catalog ADD CONSTRAINT service_catalog_category_check
  CHECK (category IN ('lab_test','imaging','health_package','procedure',
                      'consultation','physiotherapy','dental','nursing'));

ALTER TABLE service_catalog ADD COLUMN IF NOT EXISTS sub_category          TEXT DEFAULT '';
ALTER TABLE service_catalog ADD COLUMN IF NOT EXISTS unit                  TEXT DEFAULT '';
ALTER TABLE service_catalog ADD COLUMN IF NOT EXISTS reference_mrp         NUMERIC(10,2);
ALTER TABLE service_catalog ADD COLUMN IF NOT EXISTS reference_offer_price NUMERIC(10,2);

CREATE INDEX IF NOT EXISTS idx_service_catalog_subcategory
    ON service_catalog(category, sub_category) WHERE is_active;

ON CONFLICT (slug) DO UPDATE SET
    name                  = EXCLUDED.name,
    category              = EXCLUDED.category,
    sub_category          = COALESCE(EXCLUDED.sub_category, service_catalog.sub_category),
    unit                  = COALESCE(EXCLUDED.unit, service_catalog.unit),
    reference_mrp         = EXCLUDED.reference_mrp,
    reference_offer_price = EXCLUDED.reference_offer_price;

COMMIT;

NOTIFY pgrst, 'reload schema';
